from fastapi import FastAPI, Request
from fastapi.responses import StreamingResponse
from langchain_community.chat_models import ChatOpenAI
from langchain_core.messages import HumanMessage
from langchain_openai import ChatOpenAI

app = FastAPI()

llm = ChatOpenAI(
    openai_api_base="https://infer.e2enetworks.net/project/p-5729/genai/llama_3_3_70b_instruct_fp8/v1",
    openai_api_key="eyJhbGciOiJSUzI1NiIsInR5cCIgOiAiSldUIiwia2lkIiA6ICJGSjg2R2NGM2pUYk5MT2NvNE52WmtVQ0lVbWZZQ3FvcXRPUWVNZmJoTmxFIn0..LRTXhbKQ_luHvVwWBbBLMmu5MSmlhdy5ERU437XUOV37_z6Ld-1E98qeh6W5HkTrhkiw2oWmy5XPlsak1KCRcLjW38b8QUKIgFPQVh0h8VNVDwDD1ZhsxK7mknZauS9MDY43oowDa6_rjazJtJ8sTSk9fy0sRBljYON_6rO7xkY",
    model="llama_3_3_70b_instruct_fp8",
    streaming=True,
    temperature=0,
)

@app.post("/generate")
async def generate(request: Request):
    # Request not query parameter
    data = await request.json()
    prompt = data.get("prompt", "")
    messages = [HumanMessage(content=prompt)]
    # human message object of langchain

    def generate_stream():
        for chunk in llm.stream(messages):
            yield chunk.content

    return StreamingResponse(generate_stream(), media_type="text/plain")
